internal object DuaMniDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("হৌগৎলকপগা লোইননা", "থাগৎলিবসি ঐখোয়না শিরবা মতুংদা পুন্সি পীখিবা অল্লাহনি, অমসুং মহাক্কী মফমদা হল্লকপা অসিনি।", "নুংথিলদগী ৱাংখৎলকপা মতমদা, অল্লাহবু থাগৎলি।", "মসি নুমিৎ অসি নীংশিংগদবা অমসুং অকোনবগী নীংশিং থৌরমগা লোয়ননা হৌরকপা-মসি প্রোফেট সলিহ আলীহ ওসল্মনা ৱাংখৎলকপা মতমদা ইখি।"),
        "dua_leaving_home" to DuaText("য়ুম থাদোরকপা মতমদা", "আল্লাহগী মমিংদা; ঐহাক্না অল্লাহদা থাজবা থম্লি। অল্লাহ নত্তনা শক্তি অমদি শক্তি অমত্তা লৈতে।", "য়ুমদগী মপান্দা চৎপদা, অল্লাহগী ঙাক-শেন্নবগীদমক।", "ফেরেশতাশিংনা হায়ঃ'অদোম্না থৌশিল পী, অদোম্না য়েংশিনগনি অমসুং অদোম্না ঙাক-শেন্দুনা লৈগনি', অমসুং শায়তননা চৎথখি।"),
        "dua_anxiety_distress" to DuaText("শোক অমসুং অৱাবা থোক্তবা", "হে অল্লাহ, ঐহাক্না তুম্বুবু চিংনবা অমসুং অৱাবা, থৌজাল লৈতবা অমসুং অলসতা, অৱাবা অমসুং কা হেন্না থোকহনবা, শেঞ্জাও পায়বগী চুমদগী অমসুং মীশিংনা মাংহন্দবদগী ঙাকথোক্নবা হোৎনৈ।", "শোক, অৱাবা, শেঞ্জাও পায়বগী চুম অমসুং ৱাখলগী অৱাবা লৈবা মতমদা।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵স্লমনা য়াম্না তোয়না তৌনরম্মি-অৱাবা, অলসতা অমসুং শেন্দোংগী চিংনবদগী ঙাকথোক্নবনি।"),
        "dua_sayyidul_istighfar" to DuaText("সাইয়িদ অল-ইস্তিঘফার (ক্ষমাশীল প্রধান)", "হে অল্লাহ, অদোম্না ঐগী ইবরান ওই, অদোম্না নত্তনা কনাগুম্বা অমত্তনা পুকনিং তৌনবগী হক লৈতে। অদোম্না ঐঙোন্দা শেম্লম্মি অমসুং ঐহাক্না অদোমগী সেবকনি, অমসুং ঐহাক্না মতৌ করম্না তৌবা য়াবগে হায়বদু ঐহাক্না থাজবা অমসুং ৱারেপ অদু ঙাক্লম্মি। ঐহাক্না তৌখিবা ফত্তবা থবকশিংদগী ঐহাক্না নংগী মফমদা পুকচেল শেংলি। ঐহাক্না ঐগী মফমদা তৌববু থাজৈ অমসুং ঐগী পাপ অদু খঙই, মরম অদুনা ঐঙোন্দা তৌবি। মরমদি অদোম্না নত্তনা কনাগুম্বা অমত্তনা পাপ তৌবদু মাংহনদে।", "অয়ুক অমসুং নুংথিল-মসি প্রোফেট সল্লল্লাহু অলৈহি ঵স্লমনা তমজরিবা খ্বাইদগী ফবা তৌজবা অমনি।", "করিগুম্বা মদু নুংথিলগী মতমদা থাজদনা হায়রম্লবদি অমসুং নুমিদাংগী মতমদা শিরবদি, মহাক্না স্বর্গদা চংলক্কনি; মদুবু অয়ুক পুংবা মতমদা হায়রম্লবদি চপ মান্নৈ।"),
        "dua_parents" to DuaText("মমা-মপাশিংগী ওইবা তেংবাং পীননবা য়ানা ৱারোল", "হে ঐগী লাইরেম্বী, ঐহাক্না অঙাং ওইরিঙৈ মতমদুগা মখোয় অনিমক্তা নুংশিবা উৎচরি।", "মমা-মপাশিংগী কুরানিক দুআ অমা-অঙাং ওইরিঙৈ মতমদা মখোয়গী য়েংবগী মহুৎ শিন্দুনা।", "ঐখোয়গী মমা-মপাশিংগীদমক্তা মসিগী দুআ অসি শেম্নবা অল্লাহ মশামক্না ঐখোয়গী মফমদা য়াথং পীখি।"),
        "dua_entering_mosque" to DuaText("মসজিদকী মনুংদা লৈবা", "হে আল্লাহ, ঐগীদমক অদোমগী থৌজালগী থোঙ হাংদো।", "য়েৎথক্তা পায়রগা মসজিদতা চঙবা মতমদা।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵স্লমনা মসজিদতা চংনবগীদমক পাউদম ওইনা পীরম্মি।"),
        "dua_morning_asbahna" to DuaText("অয়ুক পুংবা নীংশিংবা", "ঐখোয়না অয়ুক অদু চংলক্লে অমসুং লৈবাক পুম্বনা অয়ুক অদু অল্লাহগীনি। থাগৎফম পুম্নমক অল্লাহনি। অমত্তা ওইনা, শুপ্নতগী নত্তনা, কনাগুম্বা অমত্তনা লাই খোইরম্বদা হক লৈতে। মসি মহাক্কীনি, মসি মহাক্কীনি, মসি মহাক্কীনি, অমসুং মসি মহাক্কীনি। অমসুং মহাক্না পুম্নমক শক্তি লৈবা অমনি।", "অয়ুক পুং 24দা সুন্নাহ দুআ অমা ফোংখি।", "নুমিৎ অসি অল্লাহগী নিং-খা তম্বা অমসুং মহাক্কী অমত্তা ওইবগী মশক খঙদোকপা হৌবদগী হৌরকই।"),
        "dua_evening_amsayna" to DuaText("অয়ুক পুংবা নীংশিংবা", "ঐখোয়না নুমিদাংৱাইরমদা চংলক্লে অমসুং লৈবাক পুম্বনা অল্লাহগী ওইবা নুমিদাংৱাইরমদা চংলক্লে। পুকচেল শেংবা পুম্নমক অল্লাহনি। অমত্তা ওইনা, শুপ্নতগী নত্তনা, কনাগুম্বা অমত্তনা পুকচেল শেংবগী হক লৈতে। মসি মহাক্কীনি, মসি মহাক্কীনি, মসি মহাক্কীনি, অমসুং মসি মহাক্কীনি। অমসুং মহাক্না পুম্নমক শক্তি লৈবা অমনি।", "নুমিদাংগী মতমদা সুন্নহ দুআ অমা জপখি।", "নুমিদাং অসি অল্লাহগী নিং-খা তম্বা অমসুং মহাক্কী অমত্তা ওইবগী মশক খঙদোকপা হৌবদগী হৌরকই।"),
        "dua_bismillah_la_yadurru" to DuaText("খুদোংথিবা খুদিংমক নাথৈদুনা ঙাক-শেন্নবা", "পৃথিবীদা নত্ত্রগা স্বর্গদা করিগুম্বা অমত্তা শোকহনবা ঙমদবা, অমসুং মহাক মশামক্না তাবা, খঙবা ঙম্বা, অল্লাহগী মমিংদা।", "নুমিৎ খুদিংগী অয়ুক অমসুং অয়ুক পুং 3দা হৌগৎলু।", "করিগুম্বা মহাক অসি অয়ুক অমসুং নুমিদাংগী মতমদা অহুম হন্না হায়নরবদি, মহাকবু কনা অমত্তনা শোক্নদে।"),
        "dua_raditu_billahi" to DuaText("ঈশ্বরগী লাইয়েংগীদমক নুংশিবা", "ঐহাক্না অল্লাহবু ঐগী লোর্দ ওইনা, ইস্লামবু ঐগী ধর্ম ওইনা অমসুং মুহম্মদ সলিহ আলীহ ৱাস্লম্বু ঐগী প্রোফেত ওইনা লৈদুনা নুংঙাইবা ফাওই।", "হৌখিবা হপ্তা অনী।", "অচুম্বা নুমিৎতা মহাকপু নুংঙাইহনবা হায়বসি অল্লাহগী হক অমনি।"),
        "dua_hasbiyallah" to DuaText("হাস্বিয়াল্লাহ (আল্লাহ অসি য়াম্না চাও)", "আল্লাহ অসি ঐগীদমক মতীক চারিবনি; মহাক নত্তনা লাইরেম্বী অমত্তা লৈতে। ঐহাক্না মহাক্কী মফমদা থাজবা থম্লি, অমসুং মহাক অসি শক্তি লৈরবা সিংহাসন্দা লৈবা মপুনি।", "নুমিদাংদু অসুম অসুম থেঙজিল্লক্লি।", "কুরানগী ৱাহৈ অমা; মালেম অসিগী অমসুং অকোনবগী চিংনবাশিংগী মাইয়োক্তা অল্লাহনা মতীক চারিবনি।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("সুবহানঅল্লাহি ওয়া বিহামদিহি", "ঈশ্বরবু ইকায় খুম্নজরি অমসুং থাগৎলিবসি মহাক্কীনি।", "চুৱা অমদা লৈবা চহি 100গী চাংদা", "করিগুম্বা মীওই অমনা মসি নুমিৎ অমদা চামাথোই হায়রকপগী ৱাফম অদু সমুদ্রগী ফুমগুম্বা ওইরবসু মহাক্কী পাপদু মহাক্না মাংখিগনি।"),
        "dua_tahleel_100" to DuaText("লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু", "অচুম্বা লাইয়েংগী হক অসি অল্লাহ নত্তনা, অমত্তা ওইনা, শুপ্নতগী লৈজরবসু, কনা অমত্তদা লৈতে। মহাক্কী লৈঙাকসি অমসুং মহাক্কী পুকচেল শেংবগী হকসু লৈ, অমসুং মহাক্না পোৎ খুদিংমক পাবদা শক্তি লৈ।", "মসি নুমিৎ খুদিংগী অয়ুক পুং 24দা ৱা ঙাংগনি।", "ক্রীতদাস তরাবু নীংথম্বগী মনা, অফবা থবক চাম্মগী অইবা, পাপ চাম্মগী মুথৎ, অমসুং শায়তনদগী নুমিদাং ফাওবা ঙাক-শেন্দুনা থম্বা।"),
        "dua_leaving_mosque" to DuaText("মসজিদ থাদোকপা", "হে আল্লাহ, ঐহাক্না অদোমগী থৌজাল অদুগী মতাংদা হায়জরি।", "মসজিদতগী মপান্দা লেপ্পদা খংবদা পায়বা।", "মসজিদ থাদোরকপা মতমদা অল্লাহগী থৌজাল অমসুং প্রোভিজন্নি।"),
        "dua_after_adhan" to DuaText("অদানগী মতুংদা", "হে অল্লাহ, মসিগী মপুং ফাবা ৱারোল অমসুং লিংখৎনবা লাক্কদৌরিবা লাই খোইরম্বদা, মুহম্মদ সলিহ আলীহ ওস্লম অল-ৱাসিলাহ অমসুং অফবা মগুন পীবা, অমসুং মহাকপু মহাক্না ৱারেপ লৌখিবা প্রশংসনীঙাই ওইরবা স্তেসন অদুদা পুখৎপা।", "অদান অসি লোইরবা মতুংদা।", "মসি কনাগুম্বা অমনা হায়নরবদি, মহাক্না ৱায়েল পীনবগী নুমিত্তা প্রধান মন্ত্রী সল্লল্লাহু অলৈহি ঵সল্লমগী ৱারেপ লৌগনি।"),
        "dua_after_salah_istighfar" to DuaText("ফারদ সালাহ", "ঐ অল্লাহগী ক্ষমা চানলি (হন্না হন্না)। হে অল্লাহ, অদোম্না এস-সালম ওই অমসুং মসি নংগী শান্তিনি। হে মেজেস্তি অমসুং ওনরগী মপু, অদোম্না থৌজাল ফংজরে।", "মদুগা লোয়ননা সলিমগী মতমদসু।", "মসি লাই খোইরম্বা খুদিংগী মতুংদা প্রধান মন্ত্রী শ্রী নরেন্দ্র মোদীনা ইখি।"),
        "dua_after_salah_help_dhikr" to DuaText("অদোম্না নিংশিংলকপদা মতেং পাংবা", "হে আল্লাহ, ঐহাক্না নোংখৌ নীংশিংনবা, থাগৎনবা অমসুং খ্বাইদগী ফবা মওংদা থৌজাল তৌনবগীদমক মতেং পাংই।", "লাই খোইরম্বা খুদিংগী মতুংদা-প্রোফেট সলিহ আলীহ ওসল্মনা মু'আধ (রা.) দা মসি হায়নবা পাউতাক পীখি।", "লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমগী অখন্নবা ৱারোল-লাইরেম্বীগী মফমদা ইকায়খুম্নবা অমসুং থাজবা।"),
        "dua_ayatul_kursi" to DuaText("সালাহগী মতুংদা আয়াত অল-কুর্সি", "আল্লাহ-মহাক নত্তনা লাইরেম্বী অমত্তা লৈতে, মহাক অসি মতম চুপ্পদা হিংবা ঙম্বা, অমসুং মীওই খুদিংমক য়োকখৎপা ঙম্বা অমনি। মহাক অসি নুংশা তানবা নত্ত্রগা শোইদনা থোক্তবা ঙমদে। স্বর্গ অমসুং পৃথীবিদা লৈরিবা পুম্নমক মহাকনি। মহাক্কী অয়াবা য়াওদনা মহাকগা লোয়ননা কনাগুম্বা ৱাকৎ তৌবা ঙম্লগনি? মহাক্না মখোয়গী মমাংদা লৈরিবা অমসুং মখোয়গী মতুংদা লৈরিবা অদু খঙই। অমসুং মহাক্না পাম্লিবা অদু নত্তনা মহাক্কী লৌশিং অদু মখোয়না লৌদে। মহাক্কী কুর্সি অসি স্বর্গ অমসুং পৃথিবীদা শন্দোকই, অমসুং মখোয়বু ঙাক-শেন্দুনা থম্বা অসিনা মহাকপু থিংবা ঙমদে। মহাক অসি খ্বাইদগী ৱাংবা, খ্বাইদগী চাউবা মীওইনি।", "লাই খোইরম্বদা য়াওরিবা লাইগী মতুং অমসুং শোয়নদ্রিঙৈগী মমাংদা।", "লাই খোইরম্বদা য়াওরিবা লাই খুদিংমক অমসুং পায়রগা লৈবা লাইগী মতুংদা খোইরম্বদুগী মরক্তা, নুংথিলগী মমাংদা খোইরম্বদগী, নুংথিল ফাওবা ঙাক-শেন্দুনা থম্নবগী মরক্তা, শিরবা নত্তনা অতোপ্পা অমত্তা লৈতে।"),
        "dua_before_sleep" to DuaText("শোয়নদ্রিঙৈগী মমাংদা", "হে আল্লাহ, মাগী মমিংদা ঐনা শিরোই (উনবা) অমসুং ঐ হিংই (উনবা)।", "মহাক্না শিদ্রিবা মতুংদদি মসিদা নত্তে।", "মসি নপুংসল্লাহু অলৈহি ঵স্লমনা নুংশা শুদ্রিঙৈগী মমাংদা ইখি।"),
        "dua_sleep_tasbeeh" to DuaText("তসবিয়েহ-ই-ফাতিমি অমনোযোগী", "আল্লাহবু ইকায় খুম্নজরি (33), থাগৎলিবসি অল্লাহনি (33), অল্লাহ অসি খ্বাইদগী চাউবা (34)।", "নুংশিনবা মতমদা-প্রোফেট সলিহ আলীহ ওসল্মনা মসি ফাতিমা অমসুং অলি (রা.) দা তাক্লম্মী।", "মসি থবক শুবা মীওই অমদগী হেন্না অফবা ওইগনি হায়না প্রধান মন্ত্রী নরেন্দ্র মোদীনা হায়খি।"),
        "dua_sleep_qina_adhab" to DuaText("লাই য়েকপা লাইয়েংগী ঙাক-শেনবা", "হে অল্লাহ, অদোম্না মহাক্কী থৌমীশিংবু অমুক হন্না হল্লকপা নুমিত্তা ঐহাক্না তুম্বা লাইয়েংগী থৌদোক্তগী ঙাকথোক্কনি।", "অহলনি, অহনি, অহনি, অহনি।", "নুংশা অসি শিরবা অমসুং অকোনবগী শেম-শাবা অদু নীংশিংহনবা অমা ওইহল্লি।"),
        "dua_bad_dream" to DuaText("অমনোযোগী শিক্ষার্থী", "ঐনা শাপিত শয়তানদগী অল্লাহদা শরণ লৈ।", "ফত্তবা ৱাখলগী মতুংদাঃ য়েৎথক্তা অহিংবা-থোক্তুনা অহুম হন্না থুথাখি, মদুগী মতুংদা নাকলদা হোংদোকউ।", "ফত্তবা ৱাখলনা নংবু শাওহন্দে; মসিগী মতাংদা কনা অমত্তদা হায়রুগনু।"),
        "dua_yunus" to DuaText("প্রফেট ইউনুস (এ. এস.) গী দুআ", "অদোম্না নত্তনা লাইরেম্বী অমত্তা লৈতে। অদোম্না চাওথোকচনিংঙাই ওই। তশেংনমক্কী, ঐহাক্না ফত্তবা তৌবশিংগী মরক্তা লৈ।", "ৱেল অদুগী কুয়োমদা লৈবা প্রোপেৎ য়ুনুস (এ. এস.) গী দুআ-অৱাবা খুদিংগী ওইনা।", "করিগুম্বা মুস্লিম অমনা হীরম অমহেক্তদা মসিগী দুআ অমা তৌখ্রবদি, অল্লাহনা পাউখুম পীরম্মি।"),
        "dua_karb" to DuaText("দুয়া অ্যাট টাইম অফ ডিস্ট্রেস (কার্ব)", "কনাগুম্বা অমত্তনা লাই খোইরম্বদা হক লৈরোই, মসি মহাশক্তি লৈরবা, নীংবা কায়রবা অল্লাহ নত্তনা। লাই খোইরম্বদা হক লৈবনা, মহাশক্তি লৈরবা নিংথৌগী নিংথৌ, অদুগা লাই খোইরম্বদা হক লৈবনা। লাই খোইরম্বদা হক লৈবনা, আকাশগী নিংথৌ, পৃথীবিগী নিংথৌ অমসুং নিংথিনা লাই খোইরম্বদা লাইরে।", "য়াম্না লুখ্রবা অমসুং অৱাবা নংলবা মতমশিংদদি মসিদা অৱাবা কয়া থোত্তে।", "মসি লাইরেম্বী সল্লল্লাহু অলৈহি ঵সল্লমনা অৱাবা মতমদা ইখি।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("ইয়াহ হায়য়ু য়াহ কাইয়ুম", "হে মতম চুপ্পদা হিংবা ঙম্বা, হে পুম্নমক্কী ঙাক্লৌ ওইরিবা! ঐহাক্না অদোমগী থৌজালদগী মতেং পাংই।", "করিগুম্বা ৱাফম অমনা মতম কুইনা ফোঙদোক্লম্লবদি।", "করিগুম্বা করিগুম্বা অমনা পৈগম্বর সল্লল্লাহু অলৈহি ঵স্লমদা অৱাবা পীখ্রবদি মহাক্না অসুম্না হায়গনি।"),
        "dua_hasbunallah" to DuaText("হাসবুনাল্লাহু ওয়া নি'মাল ওয়াকিল", "ঐখোয়গী ওইনদি অল্লাহ অসি য়াম্না চাওবনি অমসুং মহাক অসি খ্বাইদগী ফবা থবক শুফম অমনি।", "য়েক্নবশিং খঙদোক্নবা হোৎনরকপা মতমদা নত্ত্রগা অচৌবা খুদোংথিবা কয়া থেংনবদা।", "মসি পৈগম্বর ইব্রাহিম (এ. এস.) না মৈদা থারকপা মতমদা হায়খি, অমসুং মসি পৈগম্বর সল্লল্লাহু অলৈহি ঵স্লমনা খুদোংথিবা মতমদা হায়খি।"),
        "dua_entering_home" to DuaText("Home অচিন পাখি", "মসি ঈশ্বরগী মমিংনি।", "য়ুমদা চঙবা মতমদা অল্লাহগী মমিং অমসুং সলামনা পুকচেল শেংবা।", "অল্লাহ্ অসি চংলকপা অমসুং চাক্লেনদা নীংশিংলকপদা, শায়তাননা হায়ঃ মফম অসিদা লৈবগী মফম লৈতে অমসুং নুংশা চাবা লৈতে।"),
        "dua_travel" to DuaText("দুয়া ফর ট্র্যাভেল (রাইদিং)", "মসি ঐখোয়না তৌহনখিবা অমসুং মসি ঐখোয়না মশামক্না তৌবা ঙমখিদবা মীওই অদু চাওথোকচনিংঙাইনি; অমসুং ঐখোয়না ঐখোয়গী লোর্দতা হল্লক্কনি।", "গাড়ীদা ফমদুনা অমসুং আল্লাহু অকবর হায়না কয়ারক হন্না হায়রকপগী মতুংদা।", "সুন্নাহ ত্রাভেল দুআ-ঙাক-শেনবা অমসুং থৌজাল পীনবগীদমক।"),
        "dua_entering_market" to DuaText("কৈথেলসিদা ফৌ তায়নরম্মী।", "অচুম্বা লাইয়েংগী হক অসি অল্লাহ নত্তনা, অমত্তা ওইনা, শুপ্নতগী লৈজরক্তনা, কনা অমত্তদা লৈতে। মহাক্কী লৈঙাকসি অমসুং মহাক্কী পুকচেল শেংবগী হক লৈ। মহাক্না পুন্সি পী অমসুং শিহল্লি, অমসুং মহাক মতম চুপ্পদা হিংই অমসুং শিরোইদে। মহাক্কী খুৎদা পুম্নমক অফবা লৈ, অমসুং মহাক্না পুম্নমক শক্তি লৈবা অমনি।", "কৈথেলসিদা ফৌ তায়নরম্মী।", "হদীসতা মসিগীদমক্তা অচৌবা মনা অমা (অফবা থবক মিলিয়ন অমা) য়াওই।"),
        "dua_adam_forgiveness" to DuaText("দুয়া অফ প্রোফেট আদম (এ. এস.)", "হে ঐখোয়গী ঈপূরোই, ঐখোয়না মশামক্তা অৱাৎপা পীরি, অমসুং করিগুম্বা ঐখোয়না ঐখোয়গীদমক অৱাৎপা পীদ্রবদি, ঐখোয়না মাঙখিবাশিংগী মনুংদা অমা ওইরগনি।", "আদম অমসুং হাৱা (AS) গী মনোকপকী দুআ।", "মীওইবা খুন্নাইগী অহানবা অনকপা-অয়ামবা-অল্লাহনা মসিবু য়ানখি।"),
        "dua_abu_bakr" to DuaText("দুৱা অবু বকর (রা) দা তাক্লম্মী", "হে অল্লাহ, ঐহাক্না ইশাদা য়াম্না অৱাৎপা ইখ্রে, অমসুং অদোম্না নত্তনা কনাগুম্বা অমত্তনা পাপ তৌখিদে, মরম অদুনা ঐ মশামক্কী মফমদা ক্ষমা তৌ অদুগা ঐবু থৌগল তৌ। তশেংনমক্কী, অদোম্না য়াম্না শাওরিবা, থৌগল তৌবা মীওইনি।", "প্রফেট সলিহ আলীহ ওসল্মনা অবু বকর অস-সিদ্দিক (রা) দা লাই খোইরম্বদা (তাশাহুদকী মতুংদা) তাকখি।", "লাই খোইরম্বদা লোইরকপদা মুন্না দুৱা অমা।"),
        "dua_astaghfirullah_atubu" to DuaText("দৈনিক ইস্তিঘফার", "ঐহাক্না অল্লাহবু শাওগনবা হোৎনখি অমসুং মহাক্কী মফমদা ঐনা তৌজবা ফোংদোকপা তাখি।", "প্রধান মন্ত্রী মোদীগী মফমদা ইকায় খুম্নবা উৎচরি।", "মহাক্না হায়খি, \"ঐহাক্না নুমিৎ অমদা তরেৎ হেন্না হন্না হন্না ইশিনবা অমসুং ঈশ্বরদগী ক্ষমা লৌরকপা পামজৈ।\""),
        "dua_laylatul_qadr" to DuaText("লাইলাত অল-কদরগী দোৱা", "হে আল্লাহ, অদোম্না য়াম্না শাওবীরি অমসুং অদোম্না য়াম্না শাওবীরি, মরম অদুনা ঐঙোন্দা তৌবীমল খঙবা ঙমই।", "লায়লাত অল-কদরগীদমক আয়েশা (আর. এ.) দা তম্বিয়ু।", "রমজান অমসুং লাইলাত অল-কদরগী অরোইবা নাইতশিংগী অখন্নবা দুআ অমা।"),
        "dua_family_coolness" to DuaText("অইবী-অশাগী ঈচেল (নুপা অমসুং নুপী)", "ঐখোয়গী ইশ্বর, ঐখোয়গী ইচিল ইনাওশিং অমসুং ঐখোয়গী মচা-মশুশিংদগী ঐখোয়গী মীৎকুপ অদু নিংথিনা লৈহনবিয়ু, অমসুং অচুম্বা মীওইশিংবু লুচিংবী ওইহনবিয়ু।", "অচুম্বা পুন্সি হিংলিবা নুপা অমসুং মচাগীদমক্তা কুরানগী দুআ।", "য়ুমদা শান্তি অমসুং অফবা য়ুম্বানগীদমক।"),
        "dua_righteous_children" to DuaText("অমনোযোগী শিক্ষার্থী", "হে ঐগী ইশ্বর, ঐ ইশামদগী অশেংবা মচা-মশু অমা পীবা। তশেংনমক্কী, অদোম্না পুকনিং তাবা মীওইনি।", "প্রফেট জাকারিয়া (এ. এস.) গী দুআ।", "অঙাংশিং থিবশিংগীদমক্তা কুরানিক দুআ অমা।"),
        "dua_ibrahim_prayer_family" to DuaText("লাই খোইদারমবগী থৌদোঙ", "হে ঐগী ইশ্বর, ঐহাক্না লাই খোইরম্বদা অমসুং ঐগী মচা-মশুশিংদগী পুথোরকপা অমা ওইহনবিয়ু। হে ঐগী ইশ্বর, ঐগী পুকচেল শেংবা অদু লৌয়ু। হে ঐগী ইশ্বর, ইবগী পাউ ফংলবা নুমিত্তা ঐহাক, ঐগী মমা-মপা অমসুং থাজবশিংবু মাংহল্লো।", "মহাক অমসুং মহাক্কী মচা-মশুশিংগীদমক্তা প্রফেট ইব্রাহিম (এ. এস.) গী দুআ।", "লাই খোইথুম্বদুগী লোইশিল্লকপদা তোইনা কৌনৈ।"),
        "dua_newlywed" to DuaText("অনৌবা লুহোং-কৈহোংবগী থৌরমশিংদা হরাওবা ফোঙদোকচরি", "আল্লাহনা নোংখৌ থৌজাল পীউ, থৌজাল পীয়ু অমসুং মখোয় অনিমকপু অফবা মওংদা পুনশিনউ।", "কনাগুম্বনা মখোয়গী লুহোংবগী থৌরম অসিদা নুংঙাইবা ফোঙদোকপা মতমদা।", "সুন্নানা লুহোংবগীদমক হরাওবা ফোঙদোকচরি।"),
        "dua_before_eating" to DuaText("চাক্লেনগী মমাংদা", "(করিগুম্বা মাংখ্রবদি) অল্লাহগী মমিংদা, মসিগী হৌরকপদা অমসুং লোইশিল্লকপদা।", "চাক্লকপদা মমাংদা। করিগুম্বা মদু মাংখ্রবদি, মদু অমুক হন্না হায়য়ু।", "বিস্মিল্লাহ হায়রম্বনা শায়তনবু চান-থক্নবা শরুক য়ামিন্নবদগী ঙাকথোকই।"),
        "dua_after_eating" to DuaText("চাক্লেন মতুংদা", "মসি ঐহাক্না পীরম্বা অমসুং শক্তি নত্ত্রগা শক্তি য়াওদনা ঐহাক্না পীরম্বা অল্লাহবু থাগৎলি।", "চাক্লেন লোইরবা মতুংদদি মসিদা অৱাবা লৈরমদে।", "মসি হায়খিবশিংগী মমাংঙৈগী ওইবা পাপশিং অদু মঙাইরে।"),
        "dua_host" to DuaText("হোস্তকীদমক", "হে অল্লাহ, মখোয়বু থৌজাল পীবা, মখোয়বু শাওহনবা অমসুং মখোয়বু থৌজাল পীবা।", "হোস্ত অদুগীদমক, কনাগুম্বা অমগী য়ুমদা চাক্লক্লবা মতুংদা।", "হোস্ত অদুবু সুন্নাগী মওংদা থাগৎলি।"),
    )
}
